#!/usr/bin/env python3
"""Validate casebook records against schema v0.1.

Usage:  python casebook/validate.py casebook/cases/
Exit code 0 if every record is valid, 1 otherwise.

Deliberately dependency-free (stdlib only) so it runs anywhere without a venv.
Parses only the small YAML subset the schema uses: scalars and inline [a, b] lists.
"""

import datetime
import os
import re
import sys

CLASS = {"incident", "near_miss", "disputed"}
CONTEXT = {"research", "internal", "limited_release", "public", "unknown"}
HARM = {"none", "minor", "moderate", "severe", "unknown"}
CONFIDENCE = {"high", "medium", "low"}
MECHANISM = {
    "specification_gaming", "reward_hacking", "deceptive_or_misleading_output",
    "unsafe_capability_elicitation", "tool_misuse", "data_leakage",
    "oversight_failure", "evaluation_failure", "scaffolding_bug",
    "misuse_by_operator", "other",
}
CAUGHT_BY = {
    "pre_deployment_eval", "internal_monitoring", "human_reviewer",
    "external_researcher", "user_report", "journalist_or_public",
    "luck", "not_caught", "unknown",
}

REQUIRED = [
    "id", "title", "date_of_event", "date_recorded", "class", "system",
    "deployment_context", "harm_realised", "mechanism", "caught_by",
    "counterfactual", "sources", "confidence", "coder",
]

ID_RE = re.compile(r"^HT-\d{4}$")


def parse_front_matter(text):
    """Return dict of the leading --- delimited block."""
    if not text.startswith("---"):
        raise ValueError("file does not begin with '---' front matter")
    end = text.find("\n---", 3)
    if end == -1:
        raise ValueError("front matter is not closed with '---'")
    out = {}
    for raw in text[3:end].splitlines():
        line = raw.strip()
        if not line or line.startswith("#"):
            continue
        if ":" not in line:
            raise ValueError("cannot parse front-matter line: %r" % raw)
        key, _, value = line.partition(":")
        key, value = key.strip(), value.strip()
        if value.startswith("[") and value.endswith("]"):
            items = [v.strip().strip("'\"") for v in value[1:-1].split(",")]
            out[key] = [v for v in items if v]
        else:
            out[key] = value.strip("'\"")
    return out


def check_date(value, field, errors):
    if value == "unknown":
        return
    try:
        datetime.date.fromisoformat(value)
    except ValueError:
        errors.append("%s: not an ISO date or 'unknown': %r" % (field, value))


def check_enum(value, allowed, field, errors):
    if value not in allowed:
        errors.append("%s: %r not in %s" % (field, value, sorted(allowed)))


def validate(record):
    errors = []

    for field in REQUIRED:
        if field not in record or record[field] in ("", []):
            errors.append("missing required field: %s" % field)
    if errors:
        return errors

    if not ID_RE.match(record["id"]):
        errors.append("id: expected HT-NNNN, got %r" % record["id"])

    check_date(record["date_of_event"], "date_of_event", errors)
    check_date(record["date_recorded"], "date_recorded", errors)

    check_enum(record["class"], CLASS, "class", errors)
    check_enum(record["deployment_context"], CONTEXT, "deployment_context", errors)
    check_enum(record["harm_realised"], HARM, "harm_realised", errors)
    check_enum(record["caught_by"], CAUGHT_BY, "caught_by", errors)
    check_enum(record["confidence"], CONFIDENCE, "confidence", errors)

    mechanisms = record["mechanism"]
    if not isinstance(mechanisms, list):
        errors.append("mechanism: must be a list, e.g. [oversight_failure]")
    else:
        if not 1 <= len(mechanisms) <= 3:
            errors.append("mechanism: expected 1-3 values, got %d" % len(mechanisms))
        for m in mechanisms:
            check_enum(m, MECHANISM, "mechanism", errors)
        if "other" in mechanisms and not record.get("notes"):
            errors.append("mechanism 'other' requires a notes field")

    sources = record["sources"]
    if not isinstance(sources, list):
        errors.append("sources: must be a list of URLs")
    else:
        for url in sources:
            if not url.startswith(("http://", "https://")):
                errors.append("sources: not a URL: %r" % url)

    # Schema rule 3: a near miss means harm was prevented.
    if record["class"] == "near_miss" and record["harm_realised"] not in (
        "none", "minor", "unknown"
    ):
        errors.append(
            "class 'near_miss' is inconsistent with harm_realised %r "
            "(use 'incident')" % record["harm_realised"]
        )
    # A realised, uncontained harm is not a near miss.
    if record["caught_by"] == "not_caught" and record["class"] == "near_miss":
        errors.append("caught_by 'not_caught' is inconsistent with class 'near_miss'")

    if len(record["counterfactual"].split()) < 8:
        errors.append("counterfactual: too short to be meaningful")

    return errors


def main(argv):
    target = argv[1] if len(argv) > 1 else "casebook/cases"
    if not os.path.isdir(target):
        print("no such directory: %s" % target)
        return 1

    paths = sorted(
        os.path.join(target, n) for n in os.listdir(target) if n.endswith(".md")
    )
    if not paths:
        print("no case files found in %s (nothing to validate yet)" % target)
        return 0

    seen_ids = {}
    failed = 0
    for path in paths:
        with open(path, encoding="utf-8") as fh:
            text = fh.read()
        try:
            record = parse_front_matter(text)
        except ValueError as exc:
            print("FAIL %s\n  - %s" % (path, exc))
            failed += 1
            continue

        errors = validate(record)
        case_id = record.get("id")
        if case_id in seen_ids:
            errors.append("duplicate id, also used by %s" % seen_ids[case_id])
        elif case_id:
            seen_ids[case_id] = path

        if errors:
            failed += 1
            print("FAIL %s" % path)
            for err in errors:
                print("  - %s" % err)
        else:
            print("ok   %s  (%s)" % (path, case_id))

    print("\n%d file(s), %d failed" % (len(paths), failed))
    return 1 if failed else 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

